from revp import find_revpal, revcomp

SEQ = "TCAATGCATGCGGGTCTATATGCAT"

EXPECTED = {(4, 6), (5, 4), (6, 6), (7, 4), (17, 4), (18, 4), (20, 6), (21, 4)}


def test_known_answer():
    assert set(find_revpal(SEQ)) == EXPECTED


def test_sorted_by_position_then_length():
    result = find_revpal(SEQ)
    assert result == sorted(result)


def test_homopolymer_yields_nothing():
    assert find_revpal("AAAAAA") == []


def test_reported_substrings_are_self_revcomp():
    for pos, length in find_revpal(SEQ):
        sub = SEQ[pos - 1 : pos - 1 + length]
        assert revcomp(sub) == sub, f"({pos}, {length}): {sub}"

